add_filter( 'woocommerce_cart_subtotal', 'perfectpixel_slashed_subtotal_with_coupon', 99, 3 );

function perfectpixel_slashed_subtotal_with_coupon( $subtotal_html, $compound, $cart ) {
	$discount = (float) $cart->get_discount_total();
	if ( $discount <= 0 || $compound ) {
		return $subtotal_html;
	}
	$before = (float) $cart->get_subtotal();
	if ( $cart->display_prices_including_tax() ) {
		$before   += (float) $cart->get_subtotal_tax();
		$discount += (float) $cart->get_discount_tax();
	}
	return '<del>' . wc_price( $before ) . '</del> <ins>' . wc_price( $before - $discount ) . '</ins>';
}
